mapper.insert:
	/* QnA 등록 */
    INSERT INTO inquiry (
        question_type_id
        , title
        , question_content
        , user_id
        , visible_yn
        , answer_status 
        , created_at
    ) VALUES (
        #{qnaCategoryId}
        , #{title}
        , #{content}
        , #{userId}
        , #{isVisible}
        , '답변대기'
        , NOW()
    )

mapper.update:
/* QnA 정보 수정 (동적 쿼리) */ UPDATE inquiry
question_type_id = #{update.qnaCategoryId},
title = #{update.title},
question_content = #{update.content},
visible_yn = #{update.isVisible},
WHERE inquiry_id = #{qnaId}
